    "questionAr": "ثلاث كتل نقطية مقاديرها $1\\text{ كجم}$ و $2\\text{ كجم}$ و $3\\text{ كجم}$ موضوعة عند النقاط $(0, 0)$ و $(18, 0)$ و $(0, 24)$ بالسنتيمتر. أوجد إحداثيي مركز الثقل $G(X_G, Y_G)$.",
