    "correctAnswer": "$\\tan\\theta = 2$",
    "correctIndex": 1,
    "hintEn": "The vertical passes through A and the center of the rectangle G. If AB is along the x-axis, tan(theta) = Y_G / X_G = BC / AB.",
    "hintAr": "يمر الخط الرأسي بنقطة التعليق A وبمركز المستطيل G. ظل الزاوية مع AB يساوي ص_م / س_م = ب جـ / أب.",
    "stepByStepSolutionEn": [
      "1. Set $A$ as origin $(0, 0)$, $AB$ along x-axis, and $AD$ along y-axis.",
      "2. Center of gravity of rectangle: $G = \\left(\\frac{15}{2}, \\frac{30}{2}\\right)$.",
      "3. In free suspension, the line $AG$ is vertical.",
      "4. The angle $\\theta$ between $AB$ and the vertical satisfies: $\\tan\\theta = \\frac{Y_G}{X_G} = \\frac{15}{7.5} = \\frac{30}{15} = 2$."
    ],
    "stepByStepSolutionAr": [
      "١. نعتبر $A$ نقطة الأصل و $AB$ على محور السينات.",
      "٢. مركز ثقل المستطيل: $G = \\left(7.5, 15\\right)$.",
      "٣. الخط الرأسي في التعليق الحر هو $AG$.",
      "٤. $\\tan\\theta = \\frac{Y_G}{X_G} = \\frac{30}{15} = 2$."
    ],
    "teacherTipEn": "For a rectangular lamina suspended from a vertex, the vertical line is always its diagonal.",
    "teacherTipAr": "للصفيحة المستطيلة المعلقة من أحد رؤوسها، يكون القطر هو الخط الرأسي دائماً."
