    "questionEn": "A square lamina $ABCD$ of side $L = 14\\text{ cm}$ has a square of side $\\frac{L}{2}$ removed from corner $C$. The remaining plate is suspended freely from vertex $B(L, 0)$. Find $\\tan\\alpha$, where $\\alpha$ is the inclination angle of side $BC$ to the vertical in equilibrium.",
