      "٢. نقطة التعليق هي $B(L, 0)$.",
      "٣. الخط الرأسي يصل بين $B$ و $G$.",
      "٤. المتجه $\\vec{BG} = \\left(-\\frac{7L}{12}, \\frac{5L}{12}\\right)$.",
