    "questionEn": "Three particles of masses $m_1 = 2\\text{ kg}$ at $(0, 0)$, $m_2 = 4\\text{ kg}$ at $(10, 0)$, and $m_3 = 2\\text{ kg}$ at $(0, 10)$ are placed in a plane. What mass $m$ must be placed at point $(0, 10)$ so that the y-coordinate of the new center of gravity becomes $Y_G = 4.0\\text{ cm}$?",
    "questionAr": "وضعت ثلاث كتل $m_1 = 2\\text{ كجم}$ عند $(0, 0)$، و $m_2 = 4\\text{ كجم}$ عند $(10, 0)$، و $m_3 = 2\\text{ كجم}$ عند $(0, 10)$. ما مقدار الكتلة $m$ التي يجب وضعها عند النقطة $(0, 10)$ بحيث يصبح الإحداثي الصادي لمركز الثقل الجديد $Y_G = 4.0\\text{ سم}$؟",
